-- Merchant cost basis for loss-free negotiation floors, and richer combo offers.

alter table public.products add column if not exists cost_paise bigint not null default 0 check (cost_paise >= 0);

update public.products
set cost_paise = case id
  when '00000000-0000-0000-0000-000000000001' then 140000
  when '00000000-0000-0000-0000-000000000002' then 170000
  when '00000000-0000-0000-0000-000000000003' then 200000
  when '00000000-0000-0000-0000-000000000101' then 30000
  when '00000000-0000-0000-0000-000000000102' then 42000
  when '00000000-0000-0000-0000-000000000103' then 50000
  when '00000000-0000-0000-0000-000000000104' then 56000
end
where id in (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000002',
  '00000000-0000-0000-0000-000000000003',
  '00000000-0000-0000-0000-000000000101',
  '00000000-0000-0000-0000-000000000102',
  '00000000-0000-0000-0000-000000000103',
  '00000000-0000-0000-0000-000000000104'
);

update public.products set combo_discount_pct = 15 where id = '00000000-0000-0000-0000-000000000001';
update public.products set combo_discount_pct = 20 where id = '00000000-0000-0000-0000-000000000002';
